  /// Timestamp when option value was last modified.
  updated_at DateTime

  //----
  // RELATIONS
  //----
  option ecommerce_mall_product_options @relation(fields: [ecommerce_mall_product_option_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_product_option_id, value_code], map: "ecommerce_mall_product_option_values_ecommerce_mall_pr_fbcbf89d")
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_product_option_id, display_order], map: "ecommerce_mall_product_option_values_ecommerce_mall_pr_364ec1fa")
}

/// Product and variant-specific images for customer viewing.
///
/// Product images represent the visual media assets associated with products
