  @@unique([tracking_number, carrier_name])
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_order_fulfillment_id], map: "ecommerce_mall_shipments_ecommerce_mall_order_fulfillm_e9d53e94")
  @@index([status])
